import os


class Config:
    # ==========================================
    # Path Configuration
    # ==========================================
    # Base directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_20"
    SUBMISSION_DIR = "./submission"

    # Raw Data Paths
    TRAIN_DATA_PATH = os.path.join(INPUT_DIR, "train.json")
    TEST_DATA_PATH = os.path.join(INPUT_DIR, "test.json")

    # Metadata Paths (Generated by previous steps)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Submission Path
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Cache Paths (Deterministic Processing)
    # SBERT Embeddings (View 1)
    TRAIN_EMBEDDINGS_PATH = os.path.join(WORKING_DIR, "train_embeddings.npy")
    VAL_EMBEDDINGS_PATH = os.path.join(WORKING_DIR, "val_embeddings.npy")
    TEST_EMBEDDINGS_PATH = os.path.join(WORKING_DIR, "test_embeddings.npy")

    # Processed Dataframes (View 2 & 3 pre-processing)
    TRAIN_FEATURES_PATH = os.path.join(WORKING_DIR, "train_features.parquet")
    VAL_FEATURES_PATH = os.path.join(WORKING_DIR, "val_features.parquet")
    TEST_FEATURES_PATH = os.path.join(WORKING_DIR, "test_features.parquet")

    # ==========================================
    # Global Settings
    # ==========================================
    SEED = 42
    N_JOBS = 12  # Utilizing available vCPUs
    N_FOLDS = 5  # Stratified CV folds

    # ==========================================
    # Feature Definitions
    # ==========================================
    # View 1: Semantic Request Content
    TEXT_COLS = ["request_title", "request_text_edit_aware"]
    SBERT_MODEL_NAME = "all-MiniLM-L6-v2"

    # View 2: Supervised User Persona (Subreddits)
    SUBREDDIT_COL = "requester_subreddits_at_request"

    # View 3: Robust Metadata
    # Explicitly including timestamp as per strategy
    NUMERICAL_COLS = [
        "requester_account_age_in_days_at_request",
        "requester_days_since_first_post_on_raop_at_request",
        "requester_number_of_comments_at_request",
        "requester_number_of_comments_in_raop_at_request",
        "requester_number_of_posts_at_request",
        "requester_number_of_posts_on_raop_at_request",
        "requester_number_of_subreddits_at_request",
        "requester_upvotes_minus_downvotes_at_request",
        "requester_upvotes_plus_downvotes_at_request",
        "unix_timestamp_of_request",
    ]

    # Target Variable
    TARGET_COL = "requester_received_pizza"

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    # Partial Least Squares (PLS) for Subreddit dimensionality reduction
    # Small components to capture dense persona signals without overfitting
    PLS_N_COMPONENTS_GRID = [5, 10, 15]

    # Logistic Regression (Ridge)
    # Searching high-regularization regime (C <= 10.0)
    LR_C_GRID = [0.0001, 0.001, 0.01, 0.1, 1.0, 5.0, 10.0]
    LR_CLASS_WEIGHTS = ["balanced", None]

    # Bagging Ensemble
    BAGGING_N_ESTIMATORS = 20

    @classmethod
    def setup(cls):
        """Ensures necessary working directories exist."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Initialize directories on module load
Config.setup()
